# ---------------------------------------------------------------------------
# [10] Networking: Synology NAS mount (home/Drive -> /dat/sd via CIFS)  (2026-07-26)
# ---------------------------------------------------------------------------
# Set up the on-disk data layout /dat (valued data) with /dat/sd as the mount point for the
# Synology NAS, and mounted the personal home share's Drive folder
# (//192.168.1.10/home/Drive) there over SMB/CIFS, authenticated as NAS user NAS_USER.
# Credentials live in a root-only file so no password is ever stored in /etc/fstab or in
# this repo. Mounted via systemd automount so it connects on first access to /dat/sd and
# never blocks boot -- important because this NAS is reached over a VPN/tunnel (it answers
# at ~150 ms despite the 192.168.x address) and is not always available.
echo ">>> [10] Synology NAS mount (home/Drive -> /dat/sd via CIFS)"
sudo mkdir -p /dat/sd
sudo mkdir -p /etc/cifs
sudo chmod 700 /etc/cifs
# Credentials file (root-only, 0600). If a NAS password was supplied to the wizard it is
# written now; otherwise a manual command is printed. The password is NEVER stored in this repo.
if [ -n "${NAS_PASSWORD:-}" ]; then printf 'username=%s\npassword=%s\n' "NAS_USER" "${NAS_PASSWORD}" | sudo tee /etc/cifs/synology-nas >/dev/null; else echo "   -> create it by hand: printf 'username=NAS_USER\\npassword=YOUR_NAS_PASSWORD\\n' | sudo tee /etc/cifs/synology-nas"; fi
sudo chmod 600 /etc/cifs/synology-nas 2>/dev/null || true
# Append the fstab entry (single line), guarded so re-running never duplicates it:
grep -q ' /dat/sd cifs ' /etc/fstab || echo '//192.168.1.10/home/Drive  /dat/sd  cifs  credentials=/etc/cifs/synology-nas,uid=1000,gid=1000,file_mode=0777,dir_mode=0777,noperm,iocharset=utf8,nofail,_netdev,x-systemd.automount,x-systemd.idle-timeout=60  0  0' | sudo tee -a /etc/fstab >/dev/null
sudo systemctl daemon-reload
sudo mount -a

# ---------------------------------------------------------------------------
# [11] Networking: Make /dat accessible to every account and sandboxed (Flatpak) app  (2026-07-26)
# ---------------------------------------------------------------------------
# Opened the whole /dat tree (local data plus the /dat/sd NAS mount) to every user account
# and every application on the machine, including sandboxed Flatpak apps. Two layers were
# needed: (1) Unix permissions -- chmod 1777 on /dat (world read/write/traverse, sticky bit
# so accounts can't delete each other's files) plus the 0777+noperm CIFS options from entry
# 10; and (2) the Flatpak sandbox, which by default hides all host paths regardless of Unix
# permissions -- granting access needs the override applied at BOTH scopes -- 'flatpak
# override --filesystem=/dat' system-wide, AND 'flatpak override --user --filesystem=/dat'
# -- because Flatpak apps installed with 'flatpak install --user' (the default for a non-
# root install, and how every app on this machine is actually installed -- see entry 16
# onward) only read the user-scope override file, not the system one.
echo ">>> [11] Make /dat accessible to every account and sandboxed (Flatpak) app"
sudo chmod 1777 /dat
sudo flatpak override --filesystem=/dat
flatpak override --user --filesystem=/dat

