# ---------------------------------------------------------------------------
# [13] Power / Session: Never sleep: disable idle screen-off and automatic suspend  (2026-07-27)
# ---------------------------------------------------------------------------
# Stopped the machine from blanking the display or suspending itself after a period of
# inactivity, so it stays powered on and reachable (long builds, downloads, remote/SSH
# sessions, NAS transfers) until a shutdown or suspend is explicitly requested. This is a
# desktop workstation on permanent AC, so there is no battery-life reason to idle-suspend.
# IMPORTANT: this session is COSMIC, not GNOME -- the familiar 'org.gnome.settings-
# daemon.plugins.power' gsettings keys still exist on disk and still read 'suspend' after
# 1800s, but nothing consumes them because gnome-settings-daemon is not running. On COSMIC
# the idle policy is owned by the 'cosmic-idle' daemon, which reads the
# 'com.system76.CosmicIdle' cosmic-config component and shells out to 'systemctl suspend'
# and 'loginctl lock-session'. Its three keys are Option<u32> values in milliseconds,
# written as bare RON files, and setting each to 'None' disables that timer. By default no
# files exist and the daemon runs on its compiled-in timeouts, so the files must be created.
# These are the same files the COSMIC Settings -> Power panel writes when you choose
# 'Never', so the GUI stays consistent with this change.
echo ">>> [13] Never sleep: disable idle screen-off and automatic suspend"
mkdir -p ~/.config/cosmic/com.system76.CosmicIdle/v1
printf 'None' > ~/.config/cosmic/com.system76.CosmicIdle/v1/screen_off_time
printf 'None' > ~/.config/cosmic/com.system76.CosmicIdle/v1/suspend_on_ac_time
printf 'None' > ~/.config/cosmic/com.system76.CosmicIdle/v1/suspend_on_battery_time

