if [ -x "$HOME/.local/bin/oh-my-posh" ] && [ "$TERM" != "dumb" ] && [ -z "$INSIDE_EMACS" ]; then
    eval "$("$HOME/.local/bin/oh-my-posh" init bash --config "$HOME/.config/oh-my-posh/theme.omp.json")"
