OMPINIT

# ---------------------------------------------------------------------------
# [15] Desktop / Appearance: Square window corners (COSMIC 'Square' style)  (2026-07-27)
# ---------------------------------------------------------------------------
# Squared off the rounded corners on COSMIC windows (and, as a consequence, on every other
# themed surface -- dialogs, menus, buttons, the dock). This is the 'Square' style that
# COSMIC Settings itself offers under Desktop -> Appearance -> Style; this entry just writes
# the same files directly so a fresh image comes up square without anyone clicking through
# the GUI. COSMIC has no windows-only corner radius: window rounding is not a compositor
# setting at all, it comes from the shared theme. cosmic-comp reads the 'corner_radii' key
# out of the com.system76.CosmicTheme.* cosmic-config component and applies it as corner
# rounding inside each window's geometry, and every libcosmic app reads the same key for its
# own widgets. So the radius is a theme-wide value, and changing it for windows necessarily
# changes it everywhere. IMPORTANT -- 'Square' is not zero: libcosmic's Roundness::Square
# maps to radius_0 = 0.0 with every other step (xs/s/m/l/xl) set to 2.0, not 0.0. The 2px is
# deliberate anti-aliasing relief on the corner pixel; visually it reads as square. Window
# frames specifically use radius_s, which drops from 8.0 to 2.0.
echo ">>> [15] Square window corners (COSMIC 'Square' style)"
# 1. The 'Square' corner-radius preset, held in a variable so the exact same
#    bytes go into every theme file. $(cat <<'EOF') strips trailing newlines,
#    which matches what the Settings app writes (these files have none).
COSMIC_SQUARE_RADII=$(cat <<'RADII'
(
    radius_0: (0.0, 0.0, 0.0, 0.0),
    radius_xs: (2.0, 2.0, 2.0, 2.0),
    radius_s: (2.0, 2.0, 2.0, 2.0),
    radius_m: (2.0, 2.0, 2.0, 2.0),
    radius_l: (2.0, 2.0, 2.0, 2.0),
    radius_xl: (2.0, 2.0, 2.0, 2.0),
)
RADII
)

# 2. Write it to the dark and light themes AND to their .Builder counterparts.
#    Settings regenerates the derived theme from the Builder, so writing only
#    one side of the pair gets silently overwritten the next time you touch
#    anything on the Appearance page.
for t in CosmicTheme.Dark CosmicTheme.Dark.Builder CosmicTheme.Light CosmicTheme.Light.Builder; do
    mkdir -p ~/.config/cosmic/com.system76.$t/v1
    printf '%s' "$COSMIC_SQUARE_RADII" > ~/.config/cosmic/com.system76.$t/v1/corner_radii
done

# 3. Panel and dock, mirroring cosmic-settings' own logic for the Square style:
#    border_radius = radius_xl (2), except a panel that is flush to the screen
#    edge with no gap, which gets 0. The dock also loses its 4px padding.
for p in Panel Dock; do
    d=~/.config/cosmic/com.system76.CosmicPanel.$p/v1
    [ -d "$d" ] || continue
    gap=$(cat "$d/anchor_gap" 2>/dev/null || echo false)
    edges=$(cat "$d/expand_to_edges" 2>/dev/null || echo true)
    if [ "$gap" = "true" ] || [ "$edges" != "true" ]; then r=2; else r=0; fi
    printf '%s' "$r" > "$d/border_radius"
done
printf '0' > ~/.config/cosmic/com.system76.CosmicPanel.Dock/v1/padding

# ---------------------------------------------------------------------------
