# panel's CENTER wing into its START (left) wing, with the end wing left empty, so the icons
# hug the left edge of the screen instead of sitting centered across the full-width bar --
# the same plugins_wings/plugins_center split used by the (never-applied) design this entry
# replaces.
echo ">>> [16] Panel + Dock layout: stock top status bar, left-aligned bottom Dock"
mkdir -p ~/.config/cosmic/com.system76.CosmicAppList/v1 ~/.config/cosmic/com.system76.CosmicPanel.Dock/v1

# 1. Left-align the Dock's icons: move them from the center wing into the
#    start (left) wing, leaving the end wing empty. Previously they sat
#    in plugins_center, which centers them across the full-width bar.
cat > ~/.config/cosmic/com.system76.CosmicPanel.Dock/v1/plugins_wings <<'VALUE'
Some(([
    "com.system76.CosmicPanelWorkspacesButton",
    "com.system76.CosmicPanelAppButton",
    "com.system76.CosmicAppList",
    "com.system76.CosmicAppletMinimize",
], []))
VALUE
printf '%s' "$(cat ~/.config/cosmic/com.system76.CosmicPanel.Dock/v1/plugins_wings)" > ~/.config/cosmic/com.system76.CosmicPanel.Dock/v1/plugins_wings.tmp && mv ~/.config/cosmic/com.system76.CosmicPanel.Dock/v1/plugins_wings.tmp ~/.config/cosmic/com.system76.CosmicPanel.Dock/v1/plugins_wings
printf '%s' 'Some([])' > ~/.config/cosmic/com.system76.CosmicPanel.Dock/v1/plugins_center

# 2. Pinned apps, by desktop-file ID minus the .desktop suffix. Order here
#    is the left-to-right order in the dock.
cat > ~/.config/cosmic/com.system76.CosmicAppList/v1/favorites <<'VALUE'
[
    "com.system76.CosmicFiles",
    "com.system76.CosmicEdit",
    "com.system76.CosmicTerm",
    "com.system76.CosmicStore",
    "com.system76.CosmicSettings",
    "org.chromium.Chromium",
    "com.system76.CosmicMonitor",
]
VALUE
printf '%s' "$(cat ~/.config/cosmic/com.system76.CosmicAppList/v1/favorites)" > ~/.config/cosmic/com.system76.CosmicAppList/v1/favorites.tmp && mv ~/.config/cosmic/com.system76.CosmicAppList/v1/favorites.tmp ~/.config/cosmic/com.system76.CosmicAppList/v1/favorites

# ---------------------------------------------------------------------------
# [17] Desktop / Appearance: Custom wallpaper collection (system-wide)  (2026-07-28)
# ---------------------------------------------------------------------------
# Installed this build's own wallpaper collection system-wide so the images show up in the
# COSMIC wallpaper picker on a fresh install, for every account on the machine, without
# anyone having to browse to a folder. The source images live in the PopInstall repo under
# img/ and are copied to /usr/share/backgrounds/ -- 13 files, roughly 22 MB total, mostly
# NASA/ISS earth-and-space photography plus a few personal and landscape shots.
# /usr/share/backgrounds is the directory COSMIC's wallpaper picker opens by default:
# cosmic-settings' Wallpaper page computes its default folder by walking $XDG_DATA_DIRS
# looking for the first entry that has a 'backgrounds' subdirectory, and falling back to the
# literal /usr/share/backgrounds if none does. On this machine XDG_DATA_DIRS is the flatpak
# exports dirs, /usr/local/share, /usr/share and the snapd desktop dir, and none of the
# earlier ones has a backgrounds subdirectory -- so /usr/share/backgrounds is where the
# picker lands, and dropping files straight into it is what makes them appear without extra
# configuration. This entry only makes the images AVAILABLE; it does not pick one as the
# active wallpaper.
echo ">>> [17] Custom wallpaper collection (system-wide)"
# Resolve the PopInstall checkout that this script lives in, so the images
# are found whether install.sh is run from the repo, from a Cubic chroot, or
# as a first-boot provisioning script. Override by exporting POPINSTALL_DIR.
POPINSTALL_DIR="${POPINSTALL_DIR:-$(cd "$(dirname "${BASH_SOURCE[0]:-$0}")" && pwd)}"

if [ ! -d "$POPINSTALL_DIR/img" ]; then
    echo "    !! $POPINSTALL_DIR/img not found -- skipping wallpaper install" >&2
else
    sudo mkdir -p /usr/share/backgrounds
    # 'install -m 0644' rather than 'cp': the files in the repo are mode 0700,
    # and a plain cp would carry that through and leave the wallpapers
    # unreadable by every other account on the machine.
    find "$POPINSTALL_DIR/img" -maxdepth 1 -type f \
        \( -iname '*.jpg' -o -iname '*.jpeg' -o -iname '*.png' \) -print0 \
        | sudo xargs -0 --no-run-if-empty install -m 0644 -t /usr/share/backgrounds/
    echo "    installed $(find \"$POPINSTALL_DIR/img\" -maxdepth 1 -type f \( -iname '*.jpg' -o -iname '*.jpeg' -o -iname '*.png' \) | wc -l) wallpapers into /usr/share/backgrounds"
fi

