# [18] Development: Development prerequisites and runtimes (pip, venv, ripgrep, fd, gh, Node LTS)  (2026-07-28)
# ---------------------------------------------------------------------------
# Installed the pieces that Claude Code and everyday development on this machine assume are
# present but which Pop!_OS does not ship. Four separate gaps were found by auditing the
# live system rather than guessing. First, RIPGREP WAS NOT ACTUALLY INSTALLED: running 'rg
# --version' appeared to work and reported ripgrep 14.1.1, but 'type -a rg' shows that 'rg'
# is a SHELL FUNCTION which Claude Code injects into interactive shells, proxying to the
# ripgrep bundled inside its own binary at ~/.local/share/claude/versions/. No script,
# editor, or other tool on the system could use it, and it vanishes outside a Claude Code
# shell. The real 'ripgrep' package is installed here. Second, python3-pip and python3-venv
# were both absent even though the repo's CLAUDE.md directs per-project virtualenvs --
# 'python3 -m venv' simply failed. Third, Node.js and npm were absent, which blocks the
# Azure MCP Server VS Code extension from entry 20 (it is launched through npx). Fourth, gh
# (GitHub CLI) and fd were missing. Note that Claude Code ITSELF needs none of this: it is a
# self-contained native binary in ~/.local/share/claude, not an npm package, so Node is
# required for MCP servers and JS work rather than for the agent.
echo ">>> [18] Development prerequisites and runtimes (pip, venv, ripgrep, fd, gh, Node LTS)"
sudo apt install -y python3-pip python3-venv ripgrep fd-find gh

# Debian/Ubuntu ship fd as 'fdfind' because the name 'fd' is taken by an
# unrelated package; symlink it into ~/.local/bin so it answers to the name
# every piece of documentation uses.
mkdir -p ~/.local/bin
[ -e ~/.local/bin/fd ] || ln -s "$(command -v fdfind)" ~/.local/bin/fd

# Node.js LTS from NodeSource -- a real .deb repo, system-wide, in keeping
# with the native-tools-only rule from entry 7.
curl -fsSL https://deb.nodesource.com/setup_lts.x | sudo -E bash -
sudo apt install -y nodejs

# ---------------------------------------------------------------------------
# [19] Development: git identity, defaults, and SSH key  (2026-07-28)
# ---------------------------------------------------------------------------
# Gave git an identity and a key. git itself was already installed (2.43.0, stock with
# Pop!_OS) but had NO global configuration at all -- 'git config --global --list' returned
# nothing, so user.name and user.email were unset and there was no ~/.ssh directory. That
# matters more than it looks: git refuses to create a commit without an identity, so every
# commit attempt, including any made by Claude Code on this machine, would have failed with
# 'Author identity unknown' until this was set. Also sets two defaults worth having on a
# fresh image -- init.defaultBranch=main so new repos do not start on 'master', and
# pull.rebase=false to pin merge-on-pull behaviour rather than leaving git to print its
# 'divergent branches' hint on every pull. Finally generates an ed25519 SSH keypair, the
# modern default (smaller and faster than RSA, and accepted everywhere that matters).
echo ">>> [19] git identity, defaults, and SSH key"
git config --global user.name "Your Name"
git config --global user.email "you@example.com"
git config --global init.defaultBranch main
git config --global pull.rebase false

# ed25519 keypair for pushing. Guarded so re-running install.sh can never
# destroy an existing key -- ssh-keygen would happily overwrite it.
mkdir -p ~/.ssh && chmod 700 ~/.ssh
[ -f ~/.ssh/id_ed25519 ] || ssh-keygen -t ed25519 -C "you@example.com" \
    -f ~/.ssh/id_ed25519 -N ""

# ---------------------------------------------------------------------------
# [20] Development: Visual Studio Code + extensions  (2026-07-28)
# ---------------------------------------------------------------------------
# Installed Visual Studio Code as a native .deb from Microsoft's own apt repository, plus
# the extension set this machine's work actually calls for. VS Code had never been installed
# on this system -- there was no ~/.config/Code, no ~/.vscode, no ~/.vscode-server and no
# Microsoft apt source -- so there was no existing extension list to migrate and the set
# below was derived from evidence in the /dat/sd/JE/JE_Tech tree rather than copied from a
# previous install. The repo is used instead of the Snap Store or the standalone .tar.gz for
# the same reason recorded in entry 7: native packages only, and apt keeps it updated with
# everything else. Extensions installed: ms-python.python (132 .py files across Python/,
# RaspberryPICO/, Tetris/, PopInstall/tools/); ms-python.vscode-pylance (Python
# IntelliSense/type checking); ms-python.debugpy (Python debugging); ms-vscode.powershell
# (18 .ps1/.PS1 files under PS/); anthropic.claude-code (requested); ms-azuretools.vscode-
# azure-mcp-server (requested); ms-azuretools.vscode-azureresourcegroups
# (PS/AzureNET/Create.ps1 builds vnets/gateways); ms-vscode.azurecli (Azure CLI script
# authoring); paulober.pico-w-go (RaspberryPICO/ -- MicroPython 'machine'/'network' imports,
# .uf2 firmware); eamodio.gitlens (git workflow); timonwong.shellcheck (install.sh plus 3
# .sh files); yzhang.markdown-all-in-one (27 .md files including CLAUDE.md); redhat.vscode-
# yaml (TDAH Exercise/mempalace.yaml); tamasfe.even-better-toml (Windows-
# MCP/pyproject.toml); mechatroner.rainbow-csv (6 .csv files).
echo ">>> [20] Visual Studio Code + extensions"
sudo apt install -y wget gpg apt-transport-https

# Microsoft's signing key, dearmored into its own keyring rather than the
# deprecated global apt-key ring.
wget -qO- https://packages.microsoft.com/keys/microsoft.asc \
    | gpg --dearmor \
    | sudo install -D -o root -g root -m 644 /dev/stdin /usr/share/keyrings/microsoft.gpg

# The VS Code apt repo, pinned to that keyring via signed-by.
echo "deb [arch=amd64 signed-by=/usr/share/keyrings/microsoft.gpg] https://packages.microsoft.com/repos/code stable main" \
    | sudo tee /etc/apt/sources.list.d/vscode.list > /dev/null

sudo apt update
sudo apt install -y code

# Extensions install as the LOGGED-IN USER, never under sudo -- they land in
# ~/.vscode/extensions, and running this with root would put them in /root.
# '|| echo' rather than a bare call so one withdrawn or renamed marketplace
# ID cannot abort the whole script under 'set -e'.
for ext in \
    ms-python.python \
    ms-python.vscode-pylance \
    ms-python.debugpy \
    ms-vscode.powershell \
    anthropic.claude-code \
    ms-azuretools.vscode-azure-mcp-server \
    ms-azuretools.vscode-azureresourcegroups \
    ms-vscode.azurecli \
    paulober.pico-w-go \
    eamodio.gitlens \
    timonwong.shellcheck \
    yzhang.markdown-all-in-one \
    redhat.vscode-yaml \
    tamasfe.even-better-toml \
    mechatroner.rainbow-csv \
; do
    code --install-extension "$ext" --force \
        || echo "    !! extension failed to install: $ext" >&2
done

