# ---------------------------------------------------------------------------
# [30] Desktop / Appearance: cosmic-term: standard XTerm ANSI color scheme (fixes mc / far2l unreadable colors)  (2026-07-30)
# ---------------------------------------------------------------------------
# Fixed Midnight Commander (mc) and far2l rendering with muted, hard-to-read colors inside
# cosmic-term, despite both apps' own configs being untouched and correct (mc's active skin
# was the stock 'default.ini', far2l's palette.ini held standard values). Both are full-
# screen terminal UIs that draw using the terminal emulator's 16-color ANSI palette (mc's
# skin references colors by name -- 'blue', 'cyan', 'lightgray' -- not by RGB), so the
# actual rendered colors come entirely from whatever cosmic-term maps ANSI 0-15 to.
# Confirmed the diagnosis by running 'xterm -e mc': same mc, same skin, correct high-
# contrast colors -- proving the terminal emulator's palette, not mc or far2l, was at fault.
# cosmic-term (confirmed as this machine's default x-terminal-emulator) ships only two
# genuinely built-in color schemes, 'COSMIC Dark' and 'COSMIC Light' (hardcoded in
# src/terminal_theme.rs), which use desaturated/pastel ANSI values designed to match the
# desktop theme rather than to stay legible in dense two-pane file-manager UIs. Every other
# scheme users might expect -- XTerm, Solarized, Dracula, Gruvbox, etc. -- exists only as a
# standalone .ron file in the pop-os/cosmic-term GitHub repo's color-schemes/ folder, meant
# to be loaded via Settings' Color Scheme -> Import button; none of them ship inside the
# binary, which is why the dropdown looked empty of any 'standard' option. Traced cosmic-
# term's on-disk config format directly from its source (src/config.rs's Config/ColorScheme
# structs and src/main.rs's save_color_schemes(), which calls cosmic-config's per-key RON
# writer) and wrote the same two files by hand, populated with the maintainers' own 'XTerm
# Dark'/'XTerm Light' presets -- the real xterm(1) default 16-color palette -- then pointed
# the app's default theme selection at them. This reproduces exactly what clicking Import +
# selecting the scheme in each dropdown would have done, without needing to locate that
# button in the running UI.
echo ">>> [30] cosmic-term: standard XTerm ANSI color scheme (fixes mc / far2l unreadable colors)"
mkdir -p ~/.config/cosmic/com.system76.CosmicTerm/v1

# Back up anything already present for these four keys before overwriting.
for key in color_schemes_dark color_schemes_light syntax_theme_dark syntax_theme_light; do
    f=~/.config/cosmic/com.system76.CosmicTerm/v1/$key
    [ -f "$f" ] && cp "$f" "$f.bak.$(date +%s)"
done

# 1. Register the two color schemes. Format and field names come straight from
#    cosmic-term's own Config struct (src/config.rs): color_schemes_dark/light are
#    each a BTreeMap<ColorSchemeId, ColorScheme> keyed by a bare integer id, RON-
#    encoded. Values are the maintainer-authored 'XTerm Dark'/'XTerm Light' presets
#    from https://github.com/pop-os/cosmic-term/tree/master/color-schemes -- the
#    real xterm(1) default 16-color palette, not invented values.
COSMIC_TERM_DARK=$(cat <<'RON'
{
    0: (
        name: "XTerm Dark",
        foreground: "#FFFFFF",
        background: "#000000",
        cursor: "#FFFFFF",
        bright_foreground: "#E5E5E5",
        dim_foreground: "#DDDDDD",
        normal: (
            black: "#000000",
            red: "#CD0000",
            green: "#00CD00",
            yellow: "#CDCD00",
            blue: "#0000EE",
            magenta: "#CD00CD",
            cyan: "#00CDCD",
            white: "#E5E5E5",
        ),
        bright: (
            black: "#7F7F7F",
            red: "#FF0000",
            green: "#00FF00",
            yellow: "#FFFF00",
            blue: "#5C5CFF",
            magenta: "#FF00FF",
            cyan: "#00FFFF",
            white: "#FFFFFF",
        ),
        dim: (
            black: "#000000",
            red: "#872B22",
            green: "#549E4E",
            yellow: "#AAAB34",
            blue: "#152E69",
            magenta: "#972596",
            cyan: "#31A7A6",
            white: "#C3C3C3",
        ),
    ),
}
RON
)
COSMIC_TERM_LIGHT=$(cat <<'RON'
{
    0: (
        name: "XTerm Light",
        foreground: "#000000",
        background: "#FFFFFF",
        cursor: "#000000",
        bright_foreground: "#7F7F7F",
        dim_foreground: "#000000",
        normal: (
            black: "#000000",
            red: "#CD0000",
            green: "#00CD00",
            yellow: "#CDCD00",
            blue: "#0000EE",
            magenta: "#CD00CD",
            cyan: "#00CDCD",
            white: "#E5E5E5",
        ),
        bright: (
            black: "#7F7F7F",
            red: "#FF0000",
            green: "#00FF00",
            yellow: "#FFFF00",
            blue: "#5C5CFF",
            magenta: "#FF00FF",
            cyan: "#00FFFF",
            white: "#FFFFFF",
        ),
        dim: (
            black: "#000000",
            red: "#691F18",
            green: "#468742",
            yellow: "#94952C",
            blue: "#0B1D47",
            magenta: "#7A1A7A",
            cyan: "#288F8F",
            white: "#AEAEAE",
        ),
    ),
}
RON
)
printf '%s' "$COSMIC_TERM_DARK" > ~/.config/cosmic/com.system76.CosmicTerm/v1/color_schemes_dark
printf '%s' "$COSMIC_TERM_LIGHT" > ~/.config/cosmic/com.system76.CosmicTerm/v1/color_schemes_light

# 2. Select them as the active default (top-level Config.syntax_theme_dark/light,
#    used whenever the active profile does not itself override the theme).
printf '"XTerm Dark"' > ~/.config/cosmic/com.system76.CosmicTerm/v1/syntax_theme_dark
printf '"XTerm Light"' > ~/.config/cosmic/com.system76.CosmicTerm/v1/syntax_theme_light

# 3. Restart cosmic-term (quit all windows, reopen) so the new default is picked up.

